    # zeros not reachable from border when passing only through 0 cells
    h,w=len(g),len(g[0])
    ext=[[g[i][j]==0 for j in range(w)] for i in range(h)]
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        y,x=q.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and g[ny][nx]==0 and not seen[ny][nx]:
                seen[ny][nx]=True; q.append((ny,nx))
    return {(i,j) for i in range(h) for j in range(w) if g[i][j]==0 and not seen[i][j]}

def f(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    res=g
    for c in comps(g):
        enc=enclosed_zeros(g,c)
