from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==1 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==1 and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(c)
    return out

def enclosed_zeros(g,c):
    # zeros not reachable from border without crossing the component cells (walls)
    h,w=len(g),len(g[0])
    wall=set(c)
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and (i,j) not in wall and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and (i,j) not in wall and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        y,x=q.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and g[ny][nx]==0 and (ny,nx) not in wall and not seen[ny][nx]:
                seen[ny][nx]=True; q.append((ny,nx))
    return {(i,j) for i in range(h) for j in range(w) if g[i][j]==0 and (i,j) not in wall and not seen[i][j]}

def f(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    res=g
    for c in comps(g):
        enc=enclosed_zeros(g,c)
        if not enc: continue
        ys=[p[0] for p in c]; xs=[p[1] for p in c]
        y0,y1=min(ys)-1,max(ys)+1; x0,x1=min(xs)-1,max(xs)+1
        for i in range(max(y0,0),min(y1,h-1)+1):
            for j in range(max(x0,0),min(x1,w-1)+1):
                if (i==max(y0,0) or i==min(y1,h-1)) or (j==max(x0,0) or j==min(x1,w-1)):
                    if g[i][j]!=1: res[i][j]=2
        for i,j in enc:
            res[i][j]=3
    return res

