def enc_pockets(gi):
    h,w=len(gi),len(gi[0]); encl=set(); seen=set()
    for y in range(h):
        for x in range(w):
            if gi[y][x]==0 and (y,x) not in seen:
                st=[(y,x)]; q=set()
                while st:
                    cy,cx=st.pop(); q.add((cy,cx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<h and 0<=nx<w and gi[ny][nx]==0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                if not any(cy in(0,h-1) or cx in(0,w-1) for cy,cx in q):
                    encl|=q
    return encl
